#[test]
fn test_bhv_serialization_011_model_keys_are_written_in_declaration_order_not_sorted() {
    use petstore::models::*;
    let model = EdgeCases {
        phase: Some(EdgeCasesPhaseEnum::OUTOFSTOCK),
        permissions_note: Some("note".to_string()),
        and: Some(true),
        ..EdgeCases::default()
    };
    let wire = serde_json::to_string(&model).expect("serializes");
    let note = wire
        .find("\"permissionsNote\"")
        .expect("the note is written");
    let and = wire.find("\"and\"").expect("the and flag is written");
    let phase = wire.find("\"phase\"").expect("the phase is written");
    assert!(
        note < and && and < phase,
        "keys must follow declaration order: {}",
        wire
    );
}

