#[test]
fn test_bhv_serialization_039_rfc3339_spellings_of_one_instant_decode_to_the_same_instant() {
    use petstore::date_time::DateTime;
    let zulu: DateTime = serde_json::from_str(r#""2024-05-06T07:08:09Z""#).expect("a Z designator");
    let offset: DateTime =
        serde_json::from_str(r#""2024-05-06T17:08:09+10:00""#).expect("an offset");
    let fraction: DateTime =
        serde_json::from_str(r#""2024-05-06T07:08:09.000000000Z""#).expect("nine fraction digits");
    assert_eq!(zulu.timestamp(), offset.timestamp());
    assert_eq!(zulu.timestamp(), fraction.timestamp());
    assert_eq!(
        zulu.timestamp_subsec_nanos(),
        fraction.timestamp_subsec_nanos()
    );
}

